db.Ship.aggregate([
  {
    $unwind: "$captain"
  },
  {
    $match: {
      $or: [
        { "captain.Class": "Cutter" },
        { "captain.Class": "Armed schooner" }
      ]
    }
  },
  {
    $group: {
      _id: "$captain.Rank",
      classes: {
        $addToSet: "$captain.Class"
      }
    }
  },
  {
    $match: {
      classes: {
        $all: ["Cutter", "Armed schooner"]
      }
    }
  },
  {
    $project: {
      Rank: "$_id",
      _id: 0
    }
  }
]);

