db.jobs.aggregate([
  { $unwind: "$employees" },
  {
    $match: {
      "employees.JOB_ID": "PU_MAN"
    }
  },
  {
    $group: {
      _id: null,
      max_SALARY: { $max: "$employees.SALARY" }
    }
  },
  {
    $lookup: {
      from: "jobs",
      let: { max_SALARY: "$max_SALARY" },
      pipeline: [
        { $unwind: "$employees" },
        {
          $match: {
            $expr: { $gt: ["$employees.SALARY", "$$max_SALARY"] }
          }
        },
        {
          $project: {
            EMPLOYEE_ID: "$employees.EMPLOYEE_ID",
            FIRST_NAME: "$employees.FIRST_NAME",
            LAST_NAME: "$employees.LAST_NAME",
            JOB_ID: "$employees.JOB_ID",
            _id: 0
          }
        }
      ],
      as: "Docs1"
    }
  },
  { $unwind: "$Docs1" },
  {
    $replaceRoot: { newRoot: "$Docs1" }
  },
  {
    $project: {
      EMPLOYEE_ID: 1,
      FIRST_NAME: 1,
      LAST_NAME: 1,
      JOB_ID: 1,
      _id: 0
    }
  }
]);

