  },
  {
    $lookup: {
      from: "Allergy_Type",
      localField: "StuID",
      foreignField: "Has_Allergy.StuID",
      as: "Docs1"
    }
  },
  {
    $addFields: {
      has_food_or_animal_allergy: {
        $anyElementTrue: {
          $map: {
            input: "$Docs1",
            as: "allergy",
            in: {
              $or: [
                { $eq: ["$$allergy.AllergyType", "food"] },
                { $eq: ["$$allergy.AllergyType", "animal"] }
              ]
            }
          }
        }
      }
    }
  },
  {
    $match: {
      has_food_or_animal_allergy: false
    }
  },
  {
    $count: "count"
  }
]);

