    $sort: { courseCount: -1 }
  },
  {
    $limit: 3
  },
  {
    $lookup: {
      from: "Faculty",
      localField: "_id",
      foreignField: "FacID",
      as: "Docs1"
    }
  },
  {
    $unwind: "$Docs1"
  },
  {
    $project: {
      Fname: "$Docs1.Fname",
      Lname: "$Docs1.Lname",
      _id: 0
    }
  }
]);

